corrected_code:
'use server';

import { auth } from '@/auth';
import { db } from '@/lib/db';
import { revalidatePath } from 'next/cache';

export async function updateStaffRoleAction(formData: FormData) {
  const session = await auth();
  if (!session?.user) {
    throw new Error('Not authenticated');
  }

  const memberId = formData.get('memberId') as string;
  const newRole = formData.get('role') as string;

  const targetMember = await db.teamMember.findUnique({
    where: { id: memberId },
    include: { team: true }
  });
  if (!targetMember) throw new Error('Member not found');

  const callerMembership = await db.teamMember.findFirst({
    where: {
      teamId: targetMember.teamId,
      userId: session.user.id,
      role: 'OWNER'
    }
  });
  if (!callerMembership) {
    throw new Error('Forbidden: you must be a team owner to modify member roles');
  }

  await db.teamMember.update({
    where: { id: memberId },
    data: { role: newRole }
  });

  revalidatePath('/dashboard/team');
  return { success: true };
}
